ee2cc280e07945ccf3ca83eb1964c78d679f9c0b.template:
PLUGIN_ROOT=$(python "${CLAUDE_PLUGIN_ROOT}/bin/resolve_plugin_root.py" --plugin-name develop) || exit $?; export PLUGIN_ROOT
export CSID="${CLAUDE_CODE_SESSION_ID:-$PPID}"
IFS= read -r PYTEST_CMD < "${TMPDIR:-/tmp}/dev-pytest-cmd-${CSID}" 2>/dev/null || PYTEST_CMD=""
[ -n "$PYTEST_CMD" ] || { echo "! BLOCKED — PYTEST_CMD unresolved; re-run Project Detection"; exit 1; }
python "$PLUGIN_ROOT/bin/run_pytest_short.py" "$PYTEST_CMD" <target_test_dir>
GATE_EXIT=$?
case $GATE_EXIT in
    0|5) ;;
    1) echo "GATE FAIL: existing test baseline is red — stop before TDD; use /develop:fix first"; exit 1 ;;
    *) echo "GATE ERROR: baseline runner exit $GATE_EXIT — stop before TDD; resolve the runner error first"; exit 1 ;;
esac
